def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter

    bg = Counter(x for row in grid for x in row).most_common(1)[0][0]

    sep_rows = [r for r in range(h) if len(set(grid[r])) == 1 and grid[r][0] != bg]
    sep_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1 and grid[0][c] != bg]

    def segments(size, dividers):
        result, start = [], 0
        for d in dividers:
            if start < d:
                result.append(list(range(start, d)))
            start = d + 1
        if start < size:
            result.append(list(range(start, size)))
        return result or [list(range(size))]

    rs = segments(h, sep_rows)
    cs = segments(w, sep_cols)
    out = [row[:] for row in grid]

    for rseg in rs:
        for cseg in cs:
            for r in rseg:
                for c in cseg:
                    value = grid[r][c]
                    if value == bg:
                        continue
                    ri, ci = r - rseg[0], c - cseg[0]
                    for rr in rs:
                        for cc in cs:
                            if ri < len(rr) and ci < len(cc):
                                out[rr[ri]][cc[ci]] = value
    return out
